$ErrorActionPreference = "Stop"

$ProjectRoot = "D:\ck\two"
$Python = "D:\ck\anaconda_env\envs\two\python.exe"
$Target = Join-Path $ProjectRoot "train\diagnose_nan.py"
$Backup = "$Target.before_v5.bak"
$Experiment = "train\experiments\main\M04_single_alignn.yaml"

if (-not (Test-Path $ProjectRoot)) {
    throw "Project root not found: $ProjectRoot"
}
if (-not (Test-Path $Python)) {
    throw "Python not found: $Python"
}
if (-not (Test-Path (Split-Path $Target -Parent))) {
    throw "Target directory not found: $(Split-Path $Target -Parent)"
}

if (Test-Path $Target) {
    Copy-Item $Target $Backup -Force
    Write-Host "Backup created: $Backup"
}

$Base64 = @'

'@

$Bytes = [System.Convert]::FromBase64String($Base64)
[System.IO.File]::WriteAllBytes($Target, $Bytes)

Write-Host "Installed: $Target"

$check1 = Select-String -Path $Target -Pattern "def json_default" -SimpleMatch
$check2 = Select-String -Path $Target -Pattern "default=json_default" -SimpleMatch

if (-not $check1 -or -not $check2) {
    throw "Verification failed: JSON serializer fix is missing."
}

Write-Host "Verification passed."
Write-Host ""
Write-Host "Starting NaN diagnostic..."

Set-Location $ProjectRoot
$env:PYTHONPATH = $ProjectRoot

& $Python -m train.diagnose_nan --experiment $Experiment
if ($LASTEXITCODE -ne 0) {
    throw "NaN diagnostic failed with exit code $LASTEXITCODE"
}
